// EXPERIMENTAL: lazy AST walking for JS plugin rules, without materializing the full ESTree.
//
// Enabled with `OXLINT_JS_PLUGIN_LAZY=1`. Uses the ESTree-shaped lazy walker generated by
// `tasks/ast_tools/src/generators/raw_transfer_lazy_estree.rs`: nodes are constructed only
// when a visitor fires (or a field getter materializes them), with ESTree-exact shapes,
// `range` / lazy `loc`, and `parent` resolved through walker frames. Node identity is
// stable via a position-keyed cache, and oxlint's compiled visitor is used directly
// (the walker dispatches on the same node type IDs).
//
// Files whose visitors need ancestor tracking (complex esquery selectors) or CFG events
// are gated to the eager path in `lint.ts`.

// @ts-ignore -- generated JS
import { walkRoot } from "../generated/lazy/walk.js";
// @ts-ignore -- untyped support module
import { TOKEN } from "./lazy/support.js";

import {
  DATA_POINTER_POS_32,
  SOURCE_LEN_OFFSET,
  SOURCE_START_OFFSET,
} from "../generated/constants.ts";
import { initSourceText } from "./source_code.ts";
import * as sourceCode from "./source_code.ts";

import type { EnterExit, VisitFn } from "./visitor.ts";
import type { BufferWithArrays } from "./types.ts";

/**
 * Walk the AST lazily, directly over the raw transfer buffer.
 *
 * @param buffer - Buffer containing the file's AST
 * @param compiledVisitor - oxlint's compiled visitor, indexed by node type ID
 * @returns `true` (the lazy walk always runs; gating happens in `lint.ts`)
 */
export function tryWalkLazy(
  buffer: BufferWithArrays,
  compiledVisitor: (VisitFn | EnterExit | null)[],
): boolean {
  // Decode source text if not already decoded (string getters use it for the ASCII fast path)
  if (sourceCode.sourceText === null) initSourceText();
  const sourceText = sourceCode.sourceText!;

  // Build the `ast` wrapper object the lazy constructors expect
  const { int32 } = buffer;
  const programPos = int32[DATA_POINTER_POS_32];
  const sourceStartPos = int32[(programPos + SOURCE_START_OFFSET) >> 2];
  const sourceByteLen = int32[(programPos + SOURCE_LEN_OFFSET) >> 2];
  const ast = {
    buffer,
    sourceText,
    sourceStartPos,
    sourceByteLen,
    sourceIsAscii: sourceText.length === sourceByteLen,
    nodes: new Map(),
    token: TOKEN,
  };

  walkRoot(programPos, ast, compiledVisitor);

  return true;
}
